50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	import org.springframework.util.StringUtils;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
69	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
70	     * and a dotted domain (e.g. {@code not-an-email}).
71	     */
72	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
73	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
74	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
75	
76	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
77	    private static final String DEFAULT_COUNTRY_CODE = "61";
78	
79	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
80	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
81	
82	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
83	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
84	
85	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
86	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
87	        "ST", "STREET",
88	        "RD", "ROAD",
89	        "AVE", "AVENUE");
90	
91	    private final ClinicService clinicService;
92	
93	    private final OwnerMapper ownerMapper;
94	
95	    private final PetMapper petMapper;
96	
97	    private final VisitMapper visitMapper;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
112	        Collection<Owner> owners;
113	        if (lastName != null) {
114	            owners = this.clinicService.findOwnerByLastName(lastName);
115	        } else {
116	            owners = this.clinicService.findAllOwners();
117	        }
118	        if (owners.isEmpty()) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
127	        Owner owner = this.clinicService.findOwnerById(ownerId);
128	        if (owner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        List<String> missingFields = new ArrayList<>();
138	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
139	            missingFields.add("firstName");
140	        }
141	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
142	            missingFields.add("lastName");
143	        }
144	        // Normalize the address up front; the required-field check rejects it when it is blank
145	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
146	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
147	        if (!StringUtils.hasText(normalizedAddress)) {
148	            missingFields.add("address");
149	        }
150	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
151	            missingFields.add("city");
152	        }
153	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
154	            missingFields.add("telephone");
155	        }
156	        if (!missingFields.isEmpty()) {
157	            throw new InvalidRequestException(missingFields);
158	        }
159	        HttpHeaders headers = new HttpHeaders();
160	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
161	        // Store (and later return) the normalized address computed above.
162	        owner.setAddress(normalizedAddress);
163	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
164	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
165	        owner.setTelephone(normalizedTelephone);
166	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
167	        owner.setEmail(normalizeEmail(owner.getEmail()));
168	        // Default the (optional) registration date to the server's current date when none was supplied.
169	        if (owner.getRegistrationDate() == null) {
170	            owner.setRegistrationDate(LocalDate.now());
171	        }
172	        // Reject the request if the E.164 telephone is already used by another owner.
173	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
174	            throw new DuplicateTelephoneException(normalizedTelephone);
175	        }
176	        // Reject the request if another owner already shares the same last name and address
177	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
178	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
179	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
180	        // every existing member that does not yet carry it.
181	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
182	        if (!householdMembers.isEmpty()) {
183	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
184	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
185	            }
186	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
187	            owner.setHouseholdId(householdId);
188	            for (Owner member : householdMembers) {
189	                if (!householdId.equals(member.getHouseholdId())) {
190	                    member.setHouseholdId(householdId);
191	                    this.clinicService.saveOwner(member);
192	                }
193	            }
194	        }
195	        // Assign the customer code '<LAST3>-<NNNN>' before persisting.
196	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
197	        this.clinicService.saveOwner(owner);
198	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
199	        headers.setLocation(UriComponentsBuilder.newInstance()
200	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
201	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
207	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
208	        if (currentOwner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        currentOwner.setAddress(ownerFieldsDto.getAddress());
212	        currentOwner.setCity(ownerFieldsDto.getCity());
213	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
214	        currentOwner.setLastName(ownerFieldsDto.getLastName());
215	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
216	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
217	        this.clinicService.saveOwner(currentOwner);
218	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
219	    }
220	
221	    /**
222	     * Generate a customer code formatted {@code <LAST3>-<NNNN>}, where {@code LAST3} is the
223	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a global 4-digit
224	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
225	     *
226	     * @param lastName the owner's last name
227	     * @return the generated customer code
228	     */
229	    private String generateCustomerCode(String lastName) {
230	        String prefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
231	        int sequence = this.clinicService.findAllOwners().size() + 1;
232	        return String.format("%s-%04d", prefix.toUpperCase(Locale.ROOT), sequence);
233	    }
234	
235	    /**
236	     * Find the existing owners that live in the same household as the given values, i.e. those that
237	     * share both the last name and the address when each is compared case-insensitively with
238	     * collapsed whitespace.
239	     *
240	     * @param lastName the incoming owner's last name
241	     * @param address  the incoming owner's address
242	     * @return the matching existing owners (possibly empty)
243	     */
244	    private List<Owner> findHouseholdMembers(String lastName, String address) {
245	        String normalizedLastName = normalizeForComparison(lastName);
246	        String normalizedAddress = normalizeForComparison(address);
247	        return this.clinicService.findAllOwners().stream()
248	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
249	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
250	            .toList();
251	    }
252	
253	    /**
254	     * Generate a stable shared household identifier for the given last name and address. The value is
255	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
256	     * and address, so every owner joining the same household resolves to the same identifier. It is the
257	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
258	     *
259	     * @param lastName the household's last name
260	     * @param address  the household's address
261	     * @return the stable household identifier
262	     */
263	    private String generateHouseholdId(String lastName, String address) {
264	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
265	        try {
266	            byte[] digest = MessageDigest.getInstance("SHA-256")
267	                .digest(key.getBytes(StandardCharsets.UTF_8));
268	            StringBuilder sb = new StringBuilder(digest.length * 2);
269	            for (byte b : digest) {
270	                sb.append(String.format("%02x", b));
271	            }
272	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
273	        } catch (java.security.NoSuchAlgorithmException e) {
274	            throw new IllegalStateException("SHA-256 not available", e);
275	        }
276	    }
277	
278	    /**
279	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
280	     * single space, upper-case the result and expand common street-type abbreviations token by token
281	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
282	     * to the empty string. The result is the canonical form that is stored, returned and used for every
283	     * address comparison (household duplicate detection and the shared household id).
284	     *
285	     * @param address the raw address, may be {@code null}
286	     * @return the normalized address
287	     */
288	    private String normalizeAddress(String address) {
289	        if (address == null) {
290	            return "";
291	        }
292	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
293	        if (collapsed.isEmpty()) {
294	            return "";
295	        }
296	        String[] tokens = collapsed.split(" ");
297	        StringBuilder sb = new StringBuilder(collapsed.length());
298	        for (int i = 0; i < tokens.length; i++) {
299	            if (i > 0) {
300	                sb.append(' ');
301	            }
302	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
303	        }
304	        return sb.toString();
305	    }
306	
307	    /**
308	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
309	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
310	     *
311	     * @param value the raw value, may be {@code null}
312	     * @return the normalized value
313	     */
314	    private String normalizeForComparison(String value) {
315	        if (value == null) {
316	            return "";
317	        }
318	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
319	    }
320	
321	    /**
322	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
323	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
324	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
325	     * is returned lower-cased.
326	     *
327	     * @param email the raw email from the request payload, may be {@code null}
328	     * @return the lower-cased email, or {@code null} when none was provided
329	     */
330	    private String normalizeEmail(String email) {
331	        if (!StringUtils.hasText(email)) {
332	            return null;
333	        }
334	        if (!EMAIL_PATTERN.matcher(email).matches()) {
335	            throw new InvalidRequestException(List.of("email"));
336	        }
337	        return email.toLowerCase(Locale.ROOT);
338	    }
339	
340	    /**
341	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
342	     * already carries a leading '+' keeps its country code; otherwise the default country code
343	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
344	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
345	     * is thrown (mapped to 400 Bad Request).
346	     *
347	     * @param telephone the raw telephone from the request payload
348	     * @return the E.164 string (e.g. {@code +61412345678})
349	     */
350	    private String normalizeTelephone(String telephone) {
351	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
352	        String candidate;
